/**
 * Static server for the client. Zero dependencies -- `node:http` is enough for
 * a server whose entire job is to hand over files that are already built.
 *
 * It is a development tool, but it is not a toy: the headers it sends are the
 * ones production must send, and they are generated by the same build that
 * produced the files, so the CSP and the import-map hash cannot drift apart.
 * If you put Vaultify behind nginx or a CDN, copy `dist/csp.txt` into that
 * configuration rather than writing the policy out again by hand.
 *
 * The one thing it deliberately does *not* do is proxy the API. A proxy would
 * put the client and the API on one origin, which is more convenient and
 * strictly worse: it would hide a CORS misconfiguration until production, and
 * it would widen `connect-src` from one named origin to `'self'`.
 */

import { createServer } from "node:http";
import { readFile, stat } from "node:fs/promises";
import { extname, join, normalize, resolve, sep } from "node:path";
import { dirname } from "node:path";
import { fileURLToPath } from "node:url";

import { build } from "./build.ts";

const here = dirname(fileURLToPath(import.meta.url));
const dist = resolve(here, "dist");

const PORT = Number(process.env.PORT ?? 5173);
const HOST = process.env.HOST ?? "127.0.0.1";
const API_ORIGIN = process.env.VAULTIFY_API_ORIGIN ?? "http://localhost:4000";

const TYPES: Record<string, string> = {
  ".html": "text/html; charset=utf-8",
  ".js": "text/javascript; charset=utf-8",
  ".css": "text/css; charset=utf-8",
  ".svg": "image/svg+xml",
  ".json": "application/json; charset=utf-8",
  ".txt": "text/plain; charset=utf-8",
  ".webmanifest": "application/manifest+json",
};

const result = await build({ apiOrigin: API_ORIGIN });

const server = createServer(async (request, response) => {
  const url = new URL(request.url ?? "/", `http://${request.headers.host ?? "localhost"}`);

  // Resolve under `dist` and verify the result is still under `dist`. The
  // normalise-then-check order matters: checking the raw path for ".." misses
  // encoded traversals, which `new URL` has already decoded by this point.
  const requested = url.pathname === "/" ? "/index.html" : url.pathname;
  const candidate = resolve(join(dist, normalize(requested)));
  if (candidate !== dist && !candidate.startsWith(dist + sep)) {
    return send(response, 403, "text/plain; charset=utf-8", "Forbidden");
  }

  try {
    const info = await stat(candidate);
    if (!info.isFile()) throw new Error("not a file");
    const body = await readFile(candidate);
    return send(response, 200, TYPES[extname(candidate)] ?? "application/octet-stream", body);
  } catch {
    // No SPA fallback: this client has no routes. A 404 for a missing file is
    // the truth, and serving index.html for everything would mask typos in the
    // import map as a blank page.
    return send(response, 404, "text/plain; charset=utf-8", "Not found");
  }
});

function send(
  response: import("node:http").ServerResponse,
  status: number,
  type: string,
  body: string | Buffer,
): void {
  response.writeHead(status, {
    "Content-Type": type,
    "Content-Security-Policy": result.csp,
    "X-Content-Type-Options": "nosniff",
    "X-Frame-Options": "DENY",
    "Referrer-Policy": "no-referrer",
    "Cross-Origin-Opener-Policy": "same-origin",
    "Cross-Origin-Resource-Policy": "same-origin",
    // The vault is never in these files, but a cached bundle is a stale bundle,
    // and for a client whose integrity is the whole security story that is
    // worth more than the bandwidth.
    "Cache-Control": "no-store",
    "Permissions-Policy": "geolocation=(), camera=(), microphone=(), payment=(), usb=()",
  });
  response.end(body);
}

server.listen(PORT, HOST, () => {
  console.log(`Vaultify client  http://${HOST}:${PORT}`);
  console.log(`API origin       ${API_ORIGIN}`);
  console.log(`Modules          ${result.moduleCount} (${(result.bytes / 1024).toFixed(1)} kB, unminified)`);
  console.log("");
  console.log("The API must allow this origin:");
  console.log(`  CORS_ORIGIN=http://${HOST === "127.0.0.1" ? "localhost" : HOST}:${PORT}`);
});
